    ox, oy = (o[0], o[1]) if isinstance(o, (list, tuple)) and len(o) >= 2 else (-999, -999)

    def pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return (x[0], x[1])
        if isinstance(x, dict):
            if "x" in x and "y" in x:
                return (x["x"], x["y"])
            p = x.get("pos")
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                return (p[0], p[1])
        return None

    def cells(v):
        out = []
        if isinstance(v, dict):
            for k in ("positions", "cells", "items", "resources"):
                t = v.get(k)
                if isinstance(t, (list, tuple)):
                    for e in t:
                        p = pos(e)
                        if p is not None:
                            out.append(p)
            p = pos(v)
            if p is not None:
                out.append(p)
        elif isinstance(v, (list, tuple)):
            for e in v:
                p = pos(e)
                if p is not None:
                    out.append(p)
        return out

    rs = cells(observation.get("resources"))
    obs = set(cells(observation.get("obstacles")))
    me = (sx, sy)
    moves = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]

    def ok(nx, ny):
        return 0 <= nx < w and 0 <= ny < h and (nx, ny) not in obs

    best = None
    bd = 10**9
    for r in rs:
        d = abs(r[0] - sx) + abs(r[1] - sy)
        if d < bd:
            bd = d
            best = r

    if best is None:
        best = (w - 1 - sx, h - 1 - sy) if (sx + sy) % 2 == 0 else (0 - sx, 0 - sy)

    bx, by = best
    choice = (0, 0)
    sc = -10**9
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if not ok(nx, ny):
            continue
        d = abs(bx - nx) + abs(by - ny)
        p = -d
        if (nx, ny) == (ox, oy):
            p -= 3
        if (nx, ny) == me:
            p -= 1 if rs else 0
        if p > sc:
            sc = p
            choice = (dx, dy)
    return [int(choice[0]), int(choice[1])]

